import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, mul } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry for the card (compact metric card)
  const geometry = new PlaneGeometry(1, 1, 64, 64);
  const material = new MeshStandardNodeMaterial({
    color: 0x0b0b10, // surface color
    metalness: 0.3,
    roughness: 0.6,
    clearcoat: 0.15,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load textures (image and depth map)
  const imgPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  imgPromise.then((tex) => {
    material.mapNode = texture(tex);
    material.needsUpdate = true;
  });

  depthPromise.then((depthTex) => {
    // Displacement using TSL node
    material.displacementNode = mul(texture(depthTex), 0.1);
    material.needsUpdate = true;
  });

  // Apply cinematic primitives
  const primitiveInstances = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const inst = fn(root, prim.params);
      primitiveInstances.push(inst);
    }
  }

  // Interaction timelines
  const originalY = mesh.position.y;
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(mesh.position, {
    y: originalY + 0.15,
    duration: 0.5,
    ease: 'power3.out',
  });

  const clickTimeline = gsap.timeline({ paused: true });
  clickTimeline.to(mesh.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1)',
  });

  // Event handlers attached to userData
  root.userData.handlers = {
    hover: () => {
      hoverTimeline.play();
    },
    mouseout: () => {
      hoverTimeline.reverse();
    },
    click: () => {
      clickTimeline.restart();
      ctx.emit('hub-features.select');
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Dispose loaded textures if they were set
    if (material.mapNode && material.mapNode.value) {
      material.mapNode.value.dispose();
    }
    if (material.displacementNode && material.displacementNode.value) {
      material.displacementNode.value.dispose();
    }

    // Kill GSAP timelines
    hoverTimeline.kill();
    clickTimeline.kill();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
  };

  return root;
}
